const normalizers = Object.freeze({      // registry: one pure function per format
  csv:    (raw) => fromCsv(raw),          // -> { id, amountCents, currency, occurredAt }
  xml:    (raw) => fromXml(raw),
  legacy: ({ ref, val }) => ({ id: ref, amountCents: Math.round(val * 100), currency: 'EUR' }),
});
export function normalize(raw) {
  const body = typeof raw === 'string' ? JSON.parse(raw) : raw;
  const { type, ...payload } = body;
  const translate = Object.hasOwn(normalizers, type) ? normalizers[type] : undefined;
  if (!translate) throw new Error(`unknown wire type ${type}`);   // invalid-message path
  return translate(payload);      // every consumer sees exactly this shape
}
